"""lutgen method: a Hald CLUT generated by lutgen (https://github.com/ozwaldorf/lutgen-rs)
from the 26 colours of the flavour, then applied here like the built-in LUT
(alpha, formats and animations handled by catppuccinizer).

lutgen is an external binary, looked up in $CATPPUCCINIZER_LUTGEN, then $PATH,
then ~/.cargo/bin (and the sudo user's ~/.cargo/bin). Install: `cargo install --locked lutgen-cli` (or the AUR
package lutgen-bin).
"""
import os
import shutil
import subprocess
import tempfile
from functools import lru_cache
from pathlib import Path

from .clut import read_hald
from .options import Option
from .paths import user_home
from .palette import PALETTES

# algorithm: (lutgen flag, options it accepts besides --level/--preserve/--lum)
ALGORITHMS = {
    "blur":     ([], ["radius"]),
    "rbf":      (["--gaussian-rbf"], ["shape", "nearest"]),
    "shepard":  (["--shepards-method"], ["power", "nearest"]),
    "sampling": (["--gaussian-sampling"], ["mean", "std_dev", "iterations", "seed"]),
    "nearest":  (["--nearest-neighbor"], []),
}
# option: (type, metavar, help)
PARAMS = {
    "radius":     (float, "SIGMA", "blur: Gaussian blur radius, larger = more blending (lutgen default 8)"),
    "shape":      (float, "SHAPE", "rbf: bigger = less blending between palette colours (default 128)"),
    "nearest":    (int, "N", "rbf/shepard: nearest palette colours used, 0 = all (default 16)"),
    "power":      (float, "P", "shepard: inverse distance power (default 4)"),
    "mean":       (float, "M", "sampling: mean of the noise added per iteration (default 0)"),
    "std_dev":    (float, "SD", "sampling: standard deviation of the noise (default 20)"),
    "iterations": (int, "N", "sampling: noise iterations per colour, slower = smoother (default 512)"),
    "seed":       (int, "SEED", "sampling: noise seed (default 42080085)"),
}
GROUP = "lutgen method (--method lutgen, needs the lutgen binary)"
BLEND = ("The blending knob of an algorithm: with blur, a small --lutgen-radius gives hard "
         "transitions (close to nearest) and a large one washes colours out; with rbf, "
         "--lutgen-shape works the other way round.")
OPTIONS = [
    Option("--lutgen-algo", choices=list(ALGORITHMS), default="blur", scope="method:lutgen",
           group=GROUP, image="options-lutgen-algo.jpg",
           help="interpolation: blur (lutgen default), rbf (Gaussian RBF), "
                "shepard (inverse distance), sampling (Gaussian sampling, slow), "
                "nearest (no interpolation) (default: blur)",
           explain="blur, rbf, shepard and sampling give similar soft results with small "
                   "differences in how colours blend; nearest does not interpolate at all: "
                   "every colour snaps to one palette colour (flat, posterised look)."),
    Option("--lutgen-level", type=int, default=10, range=(2, 16), scope="method:lutgen",
           group=GROUP, help="Hald CLUT level: cube of level^2 points per axis (default: 10)"),
    Option("--lutgen-preserve", switch=True, scope="method:lutgen", group=GROUP,
           image="options-lutgen-lum.jpg",
           help="keep the original lightness after interpolation",
           explain="After a colour is replaced, its original lightness is put back: more "
                   "contrast, while the hues still come from the palette."),
    Option("--lutgen-lum", type=float, metavar="FACTOR", scope="method:lutgen", group=GROUP,
           image="options-lutgen-lum.jpg",
           explain="lutgen matches each colour to the palette by distance; this weights the "
                   "lightness in that distance. Below 1, colours find more colourful "
                   "matches; above 1, they go towards the neutrals. It is usually combined "
                   "with --lutgen-preserve.",
           help="lightness weight when matching: <1 prefers colourful matches, "
                ">1 neutral ones; usually with --lutgen-preserve (default 1)"),
    *(Option(f"--lutgen-{name.replace('_', '-')}", type=typ, metavar=metavar, help=help_,
             scope="method:lutgen", group=GROUP,
             when={"method": ["lutgen"],
                   "lutgen_algo": [a for a, (_, allowed) in ALGORITHMS.items() if name in allowed]},
             **({"image": "options-lutgen-blend.jpg", "explain": BLEND}
                if name in ("radius", "shape") else {}))
      for name, (typ, metavar, help_) in PARAMS.items()),
]


def options(a):
    """The `lutgen generate` arguments for the parsed options (tuple, hashable)."""
    flag, allowed = ALGORITHMS[a.lutgen_algo]
    out = [*flag, "--level", str(a.lutgen_level)]
    if a.lutgen_preserve:
        out.append("--preserve")
    if a.lutgen_lum is not None:
        out += ["--lum", str(a.lutgen_lum)]
    for name in PARAMS:
        value = getattr(a, f"lutgen_{name}")
        if value is None:
            continue
        if name not in allowed:
            opt = "--lutgen-" + name.replace("_", "-")
            raise SystemExit(f"{opt} does not apply to --lutgen-algo {a.lutgen_algo}")
        out += ["--" + name.replace("_", "-"), str(value)]
    return tuple(out)


def binary():
    homes = [Path.home(), user_home()]               # under sudo, also the invoking user's cargo
    for c in (os.environ.get("CATPPUCCINIZER_LUTGEN"), shutil.which("lutgen"),
              *(h / ".cargo/bin/lutgen" for h in homes)):
        if c and Path(c).is_file() and os.access(c, os.X_OK):
            return str(c)
    raise SystemExit("--method lutgen needs lutgen: `cargo install --locked lutgen-cli` "
                     "(or the AUR package lutgen-bin), or set CATPPUCCINIZER_LUTGEN")


@lru_cache(maxsize=None)
def build(flavor, opts):
    """Cube (n, n, n, 3) generated by lutgen for a flavour; opts from options()."""
    colours = [f"#{h.lstrip('#')}" for h in PALETTES[flavor].values()]
    with tempfile.TemporaryDirectory(prefix="catppuccinizer-lutgen-") as d:
        hald = Path(d) / "hald.png"
        r = subprocess.run([binary(), "generate", *opts, "-o", str(hald), "--", *colours],
                           capture_output=True, text=True)
        if r.returncode or not hald.exists():
            raise SystemExit(f"lutgen failed: {(r.stderr or r.stdout).strip()}")
        return read_hald(hald)
